import { DeskError } from './errors';

/** 对业务数量做集中检查，表单和直接调用都经这里进入。 */
export function assertRequestedQuantity(quantity: number): void {
  if (!Number.isFinite(quantity) || quantity < 1) {
    throw new DeskError('INVALID_QUANTITY');
  }
}

/** 表单空值保留为 0，由业务层给出已有错误信息。 */
export function quantityFromInput(value: string): number {
  return value.trim() === '' ? 0 : Number(value);
}

export function remainingUnits(total: number, occupied: number): number {
  return Math.max(0, total - occupied);
}

import { computed, ref } from 'vue';
import { deskRuntime } from '../application/deskRuntime';
import { readableError } from '../domain/errors';
import type { AvailabilityQuote, LoanDesk } from '../domain/types';

export function useLoanEdit(desk: LoanDesk = deskRuntime) {
  const snapshot = ref(desk.snapshot());
  const loanId = ref('L101');
  const quantity = ref(2);
  const purpose = ref('社区短片记录');
  const error = ref('');
  const success = ref('');
  const revision = ref(0);

  const loan = computed(() => snapshot.value.loans.find((row) => row.id === loanId.value));
  const readonly = computed(() => loan.value?.status !== 'CONFIRMED');
  const quote = computed<AvailabilityQuote | null>(() => {
    void revision.value;
    try { return desk.quoteEdit(loanId.value); }
    catch { return null; }
  });
  const kit = computed(() => snapshot.value.kits.find((row) => row.id === loan.value?.kitId));
  const site = computed(() => snapshot.value.sites.find((row) => row.id === loan.value?.siteId));

  function selectLoan(value: string): void {
    loanId.value = value;
    const selected = desk.getLoan(value);
    quantity.value = selected.quantity;
    purpose.value = selected.purpose;
    error.value = '';
    success.value = '';
    revision.value += 1;
  }

  function refresh(): void {
    snapshot.value = desk.snapshot();
    revision.value += 1;
  }

  function submit(): void {
    error.value = '';
    success.value = '';
    try {
      const result = desk.updateLoan({ loanId: loanId.value, quantity: quantity.value, purpose: purpose.value });
      success.value = `已保存 ${result.id}，版本 ${result.revision}`;
      refresh();
    } catch (cause) {
      error.value = readableError(cause);
    }
  }

  return { snapshot, loanId, quantity, purpose, error, success, loan, readonly, quote, kit, site, selectLoan, refresh, submit };
}

import { computed, ref } from 'vue';
import { deskRuntime } from '../application/deskRuntime';
import { readableError } from '../domain/errors';
import type { AvailabilityQuote, LoanDesk, SiteId } from '../domain/types';

export function useNewLoan(desk: LoanDesk = deskRuntime) {
  const snapshot = ref(desk.snapshot());
  const siteId = ref<SiteId>('harbor');
  const kitId = ref('camera');
  const quantity = ref(1);
  const purpose = ref('');
  const error = ref('');
  const success = ref('');
  const revision = ref(0);

  const quote = computed<AvailabilityQuote | null>(() => {
    void revision.value;
    try { return desk.quoteNew(siteId.value, kitId.value); }
    catch { return null; }
  });
  const kit = computed(() => snapshot.value.kits.find((row) => row.id === kitId.value));
  const site = computed(() => snapshot.value.sites.find((row) => row.id === siteId.value));
  const ledger = computed(() => snapshot.value.loans.filter((row) => row.siteId === siteId.value && row.kitId === kitId.value));

  function refresh(): void {
    snapshot.value = desk.snapshot();
    revision.value += 1;
  }

  function submit(): void {
    error.value = '';
    success.value = '';
    try {
      const result = desk.createLoan({ siteId: siteId.value, kitId: kitId.value,
        quantity: quantity.value, purpose: purpose.value });
      success.value = `已创建 ${result.id}，${result.quantity} 份`;
      refresh();
    } catch (cause) {
      error.value = readableError(cause);
    }
  }

  return { snapshot, siteId, kitId, quantity, purpose, error, success, quote, kit, site, ledger, refresh, submit };
}

import { DeskError } from './errors';
import { remainingUnits } from './quantity';
import type { AvailabilityQuery, AvailabilityQuote, DeskSnapshot } from './types';

/** 从快照计算借用台展示与提交使用的余量，不修改快照。 */
export function availabilityFor(snapshot: DeskSnapshot, query: AvailabilityQuery): AvailabilityQuote {
  const stock = snapshot.stocks.find((row) => row.siteId === query.siteId && row.kitId === query.kitId);
  if (!stock) throw new DeskError('UNKNOWN_STOCK');

  const occupied = snapshot.loans
    .filter((loan) => loan.kitId === query.kitId && loan.status !== 'CANCELLED')
    .reduce((sum, loan) => sum + loan.quantity, 0);

  return {
    siteId: query.siteId,
    kitId: query.kitId,
    total: stock.total,
    occupied,
    available: remainingUnits(stock.total, occupied),
  };
}

import { availabilityFor } from '../domain/availability';
import { DeskError } from '../domain/errors';
import { assertRequestedQuantity } from '../domain/quantity';
import type { AvailabilityQuote, EditLoanCommand, Loan, LoanDesk, LoanRepository, NewLoanCommand, SiteId } from '../domain/types';

/** 页面共享业务入口，仓库可注入；不接触浏览器或持久化环境。 */
export function createLoanDesk(repository: LoanRepository): LoanDesk {
  const previews = new Map<string, AvailabilityQuote>();
  const newKey = (siteId: SiteId, kitId: string) => `new:${siteId}:${kitId}`;
  const editKey = (loanId: string) => `edit:${loanId}`;

  function getLoan(loanId: string): Loan {
    const row = repository.snapshot().loans.find((loan) => loan.id === loanId);
    if (!row) throw new DeskError('LOAN_NOT_FOUND');
    return row;
  }

  function assertEditable(loan: Loan): void {
    if (loan.status !== 'CONFIRMED') throw new DeskError('READ_ONLY_LOAN');
  }

  function quoteNew(siteId: SiteId, kitId: string): AvailabilityQuote {
    const quote = availabilityFor(repository.snapshot(), { siteId, kitId });
    previews.set(newKey(siteId, kitId), quote);
    return quote;
  }

  function quoteEdit(loanId: string): AvailabilityQuote {
    const loan = getLoan(loanId);
    const quote = availabilityFor(repository.snapshot(), { siteId: loan.siteId, kitId: loan.kitId });
    previews.set(editKey(loanId), quote);
    return quote;
  }

  function createLoan(command: NewLoanCommand): Loan {
    assertRequestedQuantity(command.quantity);
    const quote = previews.get(newKey(command.siteId, command.kitId))
      ?? quoteNew(command.siteId, command.kitId);
    if (command.quantity > quote.available) throw new DeskError('INSUFFICIENT_STOCK');
    return repository.insert(command);
  }

  function updateLoan(command: EditLoanCommand): Loan {
    const loan = getLoan(command.loanId);
    assertEditable(loan);
    assertRequestedQuantity(command.quantity);
    const quote = previews.get(editKey(command.loanId)) ?? quoteEdit(command.loanId);
    if (command.quantity > quote.available) throw new DeskError('INSUFFICIENT_STOCK');
    return repository.update(command.loanId, command.quantity, command.purpose);
  }

  return { snapshot: () => repository.snapshot(), getLoan, quoteNew, quoteEdit, createLoan, updateLoan };
}

export type SiteId = 'harbor' | 'hill';
export type LoanStatus = 'DRAFT' | 'CONFIRMED' | 'COLLECTED' | 'RETURNED' | 'CANCELLED';

export interface Site {
  id: SiteId;
  name: string;
}

export interface Kit {
  id: string;
  name: string;
  depositPerUnit: number;
  description: string;
}

export interface StockRow {
  siteId: SiteId;
  kitId: string;
  total: number;
}

export interface Loan {
  id: string;
  siteId: SiteId;
  kitId: string;
  quantity: number;
  status: LoanStatus;
  purpose: string;
  revision: number;
}

export interface DeskSnapshot {
  sites: Site[];
  kits: Kit[];
  stocks: StockRow[];
  loans: Loan[];
}

export interface AvailabilityQuery {
  siteId: SiteId;
  kitId: string;
  excludeLoanId?: string;
}

export interface AvailabilityQuote {
  siteId: SiteId;
  kitId: string;
  total: number;
  occupied: number;
  available: number;
}

export interface NewLoanCommand {
  siteId: SiteId;
  kitId: string;
  quantity: number;
  purpose: string;
}

export interface EditLoanCommand {
  loanId: string;
  quantity: number;
  purpose: string;
}

export interface LoanRepository {
  snapshot(): DeskSnapshot;
  insert(command: NewLoanCommand): Loan;
  update(loanId: string, quantity: number, purpose: string): Loan;
}

export interface LoanDesk {
  snapshot(): DeskSnapshot;
  getLoan(loanId: string): Loan;
  quoteNew(siteId: SiteId, kitId: string): AvailabilityQuote;
  quoteEdit(loanId: string): AvailabilityQuote;
  createLoan(command: NewLoanCommand): Loan;
  updateLoan(command: EditLoanCommand): Loan;
}

export type DeskErrorCode = 'INVALID_QUANTITY' | 'UNKNOWN_STOCK' | 'LOAN_NOT_FOUND'
  | 'READ_ONLY_LOAN' | 'INSUFFICIENT_STOCK';

const messages: Record<DeskErrorCode, string> = {
  INVALID_QUANTITY: '数量必须为正整数',
  UNKNOWN_STOCK: '该地点未配置此器材库存',
  LOAN_NOT_FOUND: '借用单不存在',
  READ_ONLY_LOAN: '只有已确认借用单可以修改',
  INSUFFICIENT_STOCK: '可借数量不足，请按最新余量调整',
};

export class DeskError extends Error {
  readonly code: DeskErrorCode;

  constructor(code: DeskErrorCode) {
    super(messages[code]);
    this.name = 'DeskError';
    this.code = code;
  }
}

export function readableError(error: unknown): string {
  return error instanceof Error ? error.message : '操作未完成，请重新检查输入';
}

import { createMemoryLoanRepository } from '../data/memoryLoanRepository';
import { createSeedSnapshot } from '../data/seed';
import { createLoanDesk } from './loanDeskService';

/** 浏览器内的默认运行时；测试用例可直接注入自己的仓库和 desk。 */
export const deskRuntime = createLoanDesk(createMemoryLoanRepository(createSeedSnapshot()));
